<?php
declare(strict_types=1);
require __DIR__.'/../public/lib.php';require __DIR__.'/../public/planner-core.php';
function check(bool $ok,string $why):void{if(!$ok)throw new RuntimeException($why);}
function bad(array $in,string $why):void{try{dm_plan_build($in);}catch(InvalidArgumentException $e){return;}throw new RuntimeException($why);}
$input=['name'=>'Synthetic 3DGS','type'=>'circleGrid','cameraId'=>'mavic3','geometry'=>['type'=>'Polygon','coordinates'=>[[[16,48],[16.0004,48],[16.0004,48.0004],[16,48.0004],[16,48]]]],'params'=>['captureMode'=>'video','bottom'=>30,'top'=>55,'orbitRadius'=>30,'circleOverlap'=>50,'orbitLevels'=>2,'speed'=>10,'maxYawRate'=>4,'sampleFps'=>2,'photoLimit'=>150,'pitchMode'=>'auto','terrainMode'=>'off','poiReference'=>'relative']];
$r=dm_plan_build($input);$c=$r['circleGrid'];check(count($c['centers'])===2&&$c['orbits']===4,'two cells, two levels');check($r['summary']['photos']===0&&count($r['parts'])===4,'separate video orbits');check(abs($c['effectiveSpeed']-deg2rad(4)*30)<1e-9,'yaw rate speed cap');check(abs($c['nominalViewStep']-2)<1e-9,'frame view step');check($r['summary']['minHeight']===30.0&&$r['summary']['maxHeight']===55.0,'height levels');
foreach($r['parts'] as $part){$start=$part[0];$end=$part[count($part)-1];check(dm_distance($start,$end)<.001,'closed orbit');foreach($part as $pt){check($pt['poi']!==null&&abs(dm_distance($pt,['lat'=>$pt['poi'][0],'lng'=>$pt['poi'][1]])-30)<.05,'inward POI, fixed radius');check(abs($pt['speed']??INF)<=$c['effectiveSpeed']+.001,'speed bounded');check($pt['pitch']<0,'downward camera');}}
$body=array_intersect_key($r,array_flip(['name','type','cameraId','camera','geometry','params','heightReference']));check(dm_plan_build($body)['routeSha256']===$r['routeSha256'],'normalized save/load stable');
$q=$input;$q['params']['orbitLevels']=1;$single=dm_plan_build($q);check($single['summary']['maxHeight']===30.0&&count($single['parts'])===2,'one height');
$q=$input;$q['params']['photoLimit']=20;$split=dm_plan_build($q);foreach($split['parts'] as $part)check(count($part)<=20&&count(array_unique(array_column($part,'orbitIndex')))===1,'bounded sections never join targets');
foreach([['circleOverlap'=>-1],['orbitLevels'=>1.5],['targetHeight'=>30],['pitchMode'=>'manual'],['terrainMode'=>'follow'],['poiReference'=>'agl'],['sampleFps'=>0],['orbitRadius'=>0],['orbitMotion'=>'invalid']] as $params){$q=$input;$q['params']=array_replace($q['params'],$params);bad($q,'invalid input accepted: '.json_encode($params));}
$q=$input;$q['geometry']['coordinates'][]=[[16.0001,48.0001],[16.0001,48.0002],[16.0002,48.0002],[16.0002,48.0001],[16.0001,48.0001]];bad($q,'holes accepted');
$tmp=sys_get_temp_dir().'/dm-circle-grid-'.bin2hex(random_bytes(5));mkdir($tmp,0700);mkdir($tmp.'/tmp',0700);$old=getenv('DRONEMISSIONS_PRIVATE');putenv('DRONEMISSIONS_PRIVATE='.$tmp);
try{foreach(['smooth','stop'] as $motion){$plan=$r;$plan['params']['orbitMotion']=$motion;$bytes=dm_plan_kmz($plan,$plan['parts'][0],['droneEnumValue'=>'68']);$path=$tmp.'/orbit.kmz';file_put_contents($path,$bytes);$z=new ZipArchive();$z->open($path);foreach(['wpmz/template.kml','wpmz/waylines.wpml'] as $file){$xml=dm_xml($z->getFromName($file));$marks=$xml->xpath('//*[local-name()="Placemark"]');foreach($marks as $i=>$mark){$mode=dm_value($mark,'waypointTurnMode');check(abs((float)dm_value($mark,'waypointSpeed')-$c['effectiveSpeed'])<.001,'effective export speed');$smooth=$motion==='smooth'&&$i>0&&$i<count($marks)-1;check($mode===($smooth?'toPointAndPassWithContinuityCurvature':'toPointAndStopWithDiscontinuityCurvature'),'turn lifecycle');if($smooth){$d=(float)dm_value($mark,'waypointTurnDampingDist');check($d>0&&$d<dm_distance($plan['parts'][0][$i-1],$plan['parts'][0][$i])*.3,'bounded damping');}}$funcs=array_map('strval',$xml->xpath('//*[local-name()="actionActuatorFunc"]'));check(count(array_filter($funcs,fn($v)=>$v==='startRecord'))===1&&count(array_filter($funcs,fn($v)=>$v==='stopRecord'))===1,'record lifecycle');check(!in_array('takePhoto',$funcs)&&!in_array('hover',$funcs),'no photo/hover actions');}$z->close();unlink($path);}}finally{putenv('DRONEMISSIONS_PRIVATE'.($old===false?'':'='.$old));rmdir($tmp.'/tmp');rmdir($tmp);}
echo "PASS: 3DGS circle grid geometry, height levels, speed/frame metrics, replay, limits, validation and both WPML motion modes.\n";

$photo=$input;$photo['params']['captureMode']='photo';$photo['params']['photoDistance']=5;$pr=dm_plan_build($photo);check($pr['summary']['photos']>0&&$pr['summary']['videoSections']===0,'photo orbits supported');
$continuous=$input;$continuous['params']['orbitPath']='continuous';$cr=dm_plan_build($continuous);check($cr['circleGrid']['connectors']>0,'continuous connectors');check(!array_filter($cr['points'],fn($p)=>$p['breakBefore']),'no orbit breaks in continuous mode');check($cr['summary']['distance']>$r['summary']['distance'],'connections included in distance');
$continuous['params']['captureMode']='photo';$cp=dm_plan_build($continuous);check(array_filter($cp['points'],fn($p)=>($p['connector']??false)&&$p['capture']===false)!==[],'no connector photos');check($cp['summary']['uniquePhotos']===count(array_filter($cp['points'],fn($p)=>$p['capture']??true)),'photo navigation count');
$wide=$input;$wide['params']['circleOverlap']=0;$narrow=$input;$narrow['params']['circleOverlap']=80;check(dm_plan_build($narrow)['circleGrid']['orbits']>dm_plan_build($wide)['circleGrid']['orbits'],'adjustable circle spacing');
$replay=array_intersect_key($cr,array_flip(['name','type','cameraId','camera','geometry','params','heightReference']));check(dm_plan_build($replay)['routeSha256']===$cr['routeSha256'],'continuous replay');
echo "PASS: photo capture, continuous connections and recording sections, connector navigation, overlap response and replay.\n";
